<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f766e"><link rel="manifest" href="/manifest.webmanifest"><title>CRM Camp Resident MUTU</title><style>:root{font-family:system-ui;color:#172033;background:#f5f7fb}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1180px;margin:auto;padding:1rem}.top{display:flex;justify-content:space-between;align-items:center;gap:1rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1rem}.card{background:#fff;border-radius:16px;padding:1.1rem;box-shadow:0 4px 18px #17203312;margin-top:1rem}.muted{color:#64748b}button{background:#0f766e;color:#fff;border:0;border-radius:9px;padding:.65rem 1rem;cursor:pointer}input,select{padding:.65rem;border:1px solid #cbd5e1;border-radius:8px;width:100%}.row{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:.7rem}.hidden{display:none}.danger{background:#b91c1c}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:.65rem;border-bottom:1px solid #e2e8f0;text-align:left}@media(prefers-color-scheme:dark){:root{color:#e5e7eb;background:#111827}.card{background:#1f2937}.muted{color:#9ca3af}.table th,.table td{border-color:#374151}} </style></head><body><main class="wrap"><header class="top"><div><h1>CRM Camp Resident MUTU</h1><p class="muted">Manajemen tamu, kamar, booking, dan operasional</p></div><div><button id="theme">Mode gelap</button><button id="logout" class="danger hidden">Keluar</button></div></header><section id="login" class="card"><h2>Masuk</h2><form id="loginForm" class="row"><input id="email" type="email" placeholder="Email" required><input id="password" type="password" placeholder="Password" required><button>Masuk</button></form><p id="message" class="muted"></p></section><section id="app" class="hidden"><section id="stats" class="grid"></section><section class="card"><h2>Booking terbaru</h2><div style="overflow:auto"><table class="table"><thead><tr><th>Kode</th><th>Tamu</th><th>Kamar</th><th>Check in</th><th>Status</th></tr></thead><tbody id="bookings"></tbody></table></div></section><section class="card"><h2>Buat booking</h2><form id="bookingForm" class="row"><input id="guestId" type="number" placeholder="ID tamu" required><input id="roomId" type="number" placeholder="ID kamar" required><input id="checkIn" type="datetime-local" required><input id="checkOut" type="datetime-local" required><button>Simpan booking</button></form><p id="bookingMessage" class="muted"></p></section></section></main><script>const token=()=>localStorage.getItem('crm_token');const api=async(path,opt={})=>{opt.headers={...(opt.headers||{}),Accept:'application/json','Content-Type':'application/json',Authorization:`Bearer ${token()}`};const r=await fetch('/api/v1'+path,opt);const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'Permintaan gagal');return d};function show(){login.classList.toggle('hidden',!!token());app.classList.toggle('hidden',!token());logout.classList.toggle('hidden',!token());if(token())load()}async function load(){try{const d=await api('/dashboard');stats.innerHTML=[['Booking hari ini',d.bookings_today],['Check-in',d.checkins_today],['Check-out',d.checkouts_today],['Kamar tersedia',d.available_rooms],['Menunggu',d.pending_bookings]].map(x=>`<div class="card"><div class="muted">${x[0]}</div><h2>${x[1]}</h2></div>`).join('');bookings.innerHTML=d.recent_bookings.map(b=>`<tr><td>${b.booking_code}</td><td>${b.guest?.name||'-'}</td><td>${b.room?.code||'-'}</td><td>${new Date(b.check_in).toLocaleString('id-ID')}</td><td>${b.status}</td></tr>`).join('')}catch(e){message.textContent=e.message}}loginForm.onsubmit=async e=>{e.preventDefault();try{const d=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({email:email.value,password:password.value})}).then(r=>r.json());if(!d.token)throw Error(d.message||'Login gagal');localStorage.setItem('crm_token',d.token);show()}catch(e){message.textContent=e.message}};bookingForm.onsubmit=async e=>{e.preventDefault();try{await api('/bookings',{method:'POST',body:JSON.stringify({guest_id:+guestId.value,room_id:+roomId.value,check_in:checkIn.value,check_out:checkOut.value})});bookingMessage.textContent='Booking berhasil disimpan';load()}catch(e){bookingMessage.textContent=e.message}};logout.onclick=()=>{localStorage.removeItem('crm_token');show()};theme.onclick=()=>document.documentElement.classList.toggle('dark');show();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');</script></body></html>